import sys

def main():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    a = [int(x) for x in data[1:n+1]]

    has_multiple_peaks = False
    for i in range(1, n - 1):
        if a[i - 1] > a[i] and a[i] < a[i + 1]:
            has_multiple_peaks = True
            break

    if has_multiple_peaks:
        print("S")
    else:
        print("N")

if __name__ == '__main__':
